-- Photos, fees and emails are untouched. Conflicts with existing data are not changed; see Project doc ccd/profile-research-review.md.
update public.artists set bio=case when coalesce(bio,'')='' then $v$Aayna is a DJ and producer whose sets are shaped by the Roland TB-303 and 1980s and 1990s acid house. She has played Magnetic Fields, DGTL, Echoes of Earth and Grasslands Festival in Nepal, and played for the UK community Keep Hush.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Acid House$v$,$v$Electro$v$,$v$Breaks$v$] else genres end,soundcloud=case when coalesce(soundcloud,'')='' then $v$https://soundcloud.com/user-519313833$v$ else soundcloud end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://magneticfields.in/artists/aayna","https://dgtl-festival.com/en/artists/aayna/"],"genres":["https://magneticfields.in/artists/aayna","https://dgtl-festival.com/en/artists/aayna/"],"soundcloud":["https://dgtl-festival.com/en/artists/aayna/"]}}$v$::jsonb),updated_at=now() where slug=$v$aayna$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Abhi Meer is a Mumbai DJ, producer, synthesist and radio host who works with modular synths and drones. He represented Resident Advisor at Magnetic Fields, played New Delhi's first Boiler Room, hosts shows on boxout.fm, and released the EP Omerta.$v$ else bio end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Mumbai, India$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"based_city":["https://www.thewildcity.com/artists/4526-Abhi Meer"],"bio":["https://www.thewildcity.com/artists/4526-Abhi Meer"],"mix_url":["https://refugeworldwide.com/radio/spicetape-asmi-shetty-and-abhi-meer-13-jul-2023"]},"mix_note":"Spicetape | Asmi Shetty & Abhi Meer, Refuge Worldwide, 13 Jul 2023 (radio show page with play button; shared with host Asmi Shetty)"}$v$::jsonb),updated_at=now() where slug=$v$abhi-meer$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Alex Kassian is a Kyoto-born producer and DJ based in Berlin. He is one half of Opal Sunn with Hiroaki OBA and has released on Utopia, including the Hidden Tropics EP in 2018, and on Love On The Rocks.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Electronica$v$,$v$Leftfield$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Berlin, Germany$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"based_city":["https://2023.magneticfields.in/artists/alex-kassian","https://oye-records.com/releases/alex-kassian-hidden-tropics"],"bio":["https://2023.magneticfields.in/artists/alex-kassian","https://oye-records.com/releases/alex-kassian-hidden-tropics"],"genres":["https://oye-records.com/releases/alex-kassian-hidden-tropics"]}}$v$::jsonb),updated_at=now() where slug=$v$alex-kassian$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Anish Kumar is a Britain-based DJ and producer making house and Italo disco with sampled Indian and Bollywood sounds. His AK Cuts series runs across four EPs, from October 2025 to July 2026. He has sold out Village Underground in London and played Panorama Bar in Berlin.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$House$v$,$v$Italo Disco$v$] else genres end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://www.thewildcity.com/news/21746-anish-kumar-concludes-4-ep-anthology-ak-cuts"],"genres":["https://www.thewildcity.com/news/21746-anish-kumar-concludes-4-ep-anthology-ak-cuts"],"press":["https://www.thewildcity.com/news/21746-anish-kumar-concludes-4-ep-anthology-ak-cuts"]}}$v$::jsonb),updated_at=now() where slug=$v$anish-kumar$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Audio Units is a brother duo making hardware-driven techno inspired by art, science fiction and technology. They have released on Molecular, Newrhythmic, Dynamic Reflection and Illegal Alien, and played DGTL.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Techno$v$] else genres end,soundcloud=case when coalesce(soundcloud,'')='' then $v$https://soundcloud.com/audiounits$v$ else soundcloud end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://dgtl-festival.com/en/artists/audio-unites/"],"genres":["https://dgtl-festival.com/en/artists/audio-unites/"],"soundcloud":["https://dgtl-festival.com/en/artists/audio-unites/"]}}$v$::jsonb),updated_at=now() where slug=$v$audio-units$v$;
