update public.artists set bio=case when coalesce(bio,'')='' then $v$Blawan is Jamie Roberts, a DJ and producer from Barnsley, South Yorkshire. He has released on Hessle Audio, R&S and XL Recordings, runs the Ternesc label, and records with Pariah as Karenn. His album SickElixir came out on XL in 2025.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Techno$v$,$v$Garage$v$,$v$Industrial Techno$v$] else genres end,instagram=case when coalesce(instagram,'')='' then $v$blawan$v$ else instagram end,website=case when coalesce(website,'')='' then $v$https://blawan.com$v$ else website end,soundcloud=case when coalesce(soundcloud,'')='' then $v$https://soundcloud.com/blawan$v$ else soundcloud end,spotify=case when coalesce(spotify,'')='' then $v$https://open.spotify.com/artist/64kN9EkSTHYhda2FupL0KI$v$ else spotify end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"high","sources":{"bio":["https://en.wikipedia.org/wiki/Blawan"],"genres":["https://en.wikipedia.org/wiki/Blawan"],"website":["https://blawan.com"],"instagram":["https://blawan.com"],"soundcloud":["https://blawan.com"],"spotify":["https://blawan.com"]}}$v$::jsonb),updated_at=now() where slug=$v$blawan$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Chhabb is Rahul Chhabria, a DJ and producer born and raised in Mumbai and a key name in India's experimental electronic scene. He has played with The Bunker New York and Giegling, and appears on Padmini Records' compilation Yaar-Dost vol. 2.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Experimental$v$,$v$Electronic$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Mumbai, India$v$ else based_city end,soundcloud=case when coalesce(soundcloud,'')='' then $v$https://www.soundcloud.com/imaginary-friend-4$v$ else soundcloud end,mix_url=case when coalesce(mix_url,'')='' then $v$https://thebunkerny.com/podcasts/161-chhabb$v$ else mix_url end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"based_city":["https://www.thewildcity.com/artists/3658-chhabb","https://ra.co/dj/chhabb"],"bio":["https://www.thewildcity.com/artists/3658-chhabb","https://ra.co/dj/chhabb"],"genres":["https://www.thewildcity.com/artists/3658-chhabb"],"soundcloud":["https://ra.co/dj/chhabb"],"mix_url":["https://thebunkerny.com/podcasts/161-chhabb"]},"mix_note":"The Bunker Podcast 161: Chhabb, The Bunker New York, made ahead of its Mumbai and Bangalore dates in January 2018"}$v$::jsonb),updated_at=now() where slug=$v$chhabb$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Deena Abdelwahed is a Tunisian producer and DJ based in Paris. Her debut EP Klabb came out on InFiné in 2017, followed by the album Khonnar in 2018. She plays club and electronic music, from industrial techno to Arabic rhythms like mahraganat and dabke.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Club$v$,$v$Techno$v$,$v$Electronic$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Paris, France$v$ else based_city end,instagram=case when coalesce(instagram,'')='' then $v$deena___abdelwahed$v$ else instagram end,spotify=case when coalesce(spotify,'')='' then $v$https://open.spotify.com/artist/20fUkJZtm2I6zdIuj2XpgV$v$ else spotify end,mix_url=case when coalesce(mix_url,'')='' then $v$https://nts.live/shows/guests/episodes/deena-abdelwahed-29th-march-2019$v$ else mix_url end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"high","sources":{"bio":["https://deenabdelwahed.bandcamp.com","https://www.ableton.com/en/blog/deena-abdelwahed-confounding-expectations/"],"based_city":["https://deenabdelwahed.bandcamp.com","https://www.ableton.com/en/blog/deena-abdelwahed-confounding-expectations/"],"genres":["https://www.ableton.com/en/blog/deena-abdelwahed-confounding-expectations/","https://nts.live/shows/guests/episodes/deena-abdelwahed-29th-march-2019"],"instagram":["https://deenabdelwahed.bandcamp.com"],"spotify":["https://deenabdelwahed.bandcamp.com"],"mix_url":["https://nts.live/shows/guests/episodes/deena-abdelwahed-29th-march-2019"]},"mix_note":"Deena Abdelwahed & DJ Moth, NTS Radio guest hour, 29 March 2019"}$v$::jsonb),updated_at=now() where slug=$v$deena-abdelwahed$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$DJ Fart in the Club is a Seoul-born DJ based in Berlin. She has had a monthly show on NTS Radio since 2022 and co-runs the Imaginary Friend party series. Her sets run through house, techno and breaks. Her Daisychain mix was named best mix of 2021 by Resident Advisor.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$House$v$,$v$Techno$v$,$v$Breaks$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Berlin, Germany$v$ else based_city end,instagram=case when coalesce(instagram,'')='' then $v$djfartintheclub$v$ else instagram end,mix_url=case when coalesce(mix_url,'')='' then $v$https://www.nts.live/shows/dj-fart-in-the-club/episodes/dj-fart-in-the-club-10th-november-2023$v$ else mix_url end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://horstartsandmusic.com/performers/dj-fart-in-the-club","https://www.nts.live/shows/dj-fart-in-the-club"],"based_city":["https://www.nts.live/shows/dj-fart-in-the-club","https://horstartsandmusic.com/performers/dj-fart-in-the-club"],"genres":["https://www.nts.live/shows/dj-fart-in-the-club/episodes/dj-fart-in-the-club-10th-november-2023"],"instagram":["https://www.nts.live/shows/dj-fart-in-the-club"],"mix_url":["https://www.nts.live/shows/dj-fart-in-the-club/episodes/dj-fart-in-the-club-10th-november-2023"]},"mix_note":"DJ Fart in the Club, NTS Radio, 10 November 2023 (one hour monthly show)"}$v$::jsonb),updated_at=now() where slug=$v$dj-fart-in-the-club$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$DJ Pants is the alias of Aditya Mehta, a multidisciplinary artist and live sound engineer. He plays Balearic beat, disco, boogie, house and street soul, moving from relaxed daytime sets to club energy. He is on the Magnetic Fields artist roster.$v$ else bio end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://magneticfields.in/artists/dj-pants"]}}$v$::jsonb),updated_at=now() where slug=$v$dj-pants$v$;
