update public.artists set bio=case when coalesce(bio,'')='' then $v$Green Park is an indie pop trio from New Delhi, formed in late 2021. The band is Arpan Kumar on guitar and vocals, Siddharth Gupta on bass and Rishabh Singh on drums. Their debut album Newly Aged came out in March 2024.$v$ else bio end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://homegrown.co.in/homegrown-creators/newly-aged-does-green-parks-debut-album-signal-a-homegrown-indie-band-resurgence"]}}$v$::jsonb),updated_at=now() where slug=$v$green-park$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$HAAi (Teneil Throssell) is an Australian-born DJ and producer based in London. She plays techno, house and leftfield club music and has released on Mute and !K7, including DJ-Kicks: HAAi in 2023. Her BBC Radio 1 Essential Mix was named Essential Mix of the Year 2018.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Techno$v$,$v$House$v$,$v$Leftfield$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$London, United Kingdom$v$ else based_city end,instagram=case when coalesce(instagram,'')='' then $v$haaihaaihaai$v$ else instagram end,spotify=case when coalesce(spotify,'')='' then $v$https://open.spotify.com/artist/0pkLgeB9j465x1QB2kRoy4$v$ else spotify end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://hashbrandnew.com/Artists/Haai","https://mixmag.net/read/haai-bbc-essential-mix-2018-news","https://www.mixcloud.com/loverecordstores/haai/"],"based_city":["https://hashbrandnew.com/Artists/Haai","https://haai.bandcamp.com","https://www.mixcloud.com/loverecordstores/haai/"],"instagram":["https://hashbrandnew.com/Artists/Haai"],"spotify":["https://hashbrandnew.com/Artists/Haai"]}}$v$::jsonb),updated_at=now() where slug=$v$haai$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Hunee is a DJ and producer who grew up in Bochum, Germany, and is now based in Amsterdam. He plays house, funk and soul and runs the Lifetones label. His album Hunch Music came out on Rush Hour.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$House$v$,$v$Funk$v$,$v$Soul$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Amsterdam, Netherlands$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://ra.co/dj/hunee/biography"],"based_city":["https://ra.co/dj/hunee/biography"]}}$v$::jsonb),updated_at=now() where slug=$v$hunee$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Hybrid Protokol is a Kolkata duo of Soumajit Ghosh and Aneesh Basu, formed in 2015. They make progressive electronica mixed with breaks, acid and techno. They have released on Hot Elephant Music and Qilla Records, and played a Boiler Room set in April 2022.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Electronica$v$,$v$Breaks$v$,$v$Acid$v$,$v$Techno$v$] else genres end,mix_url=case when coalesce(mix_url,'')='' then $v$https://www.thewildcity.com/mixes/3136-wild-city-117-hybrid-protokol$v$ else mix_url end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://es-mx.ra.co/dj/hybridprotokol/biography","https://www.thewildcity.com/artists/3610-Hybrid Protokol"],"based_city":["https://es-mx.ra.co/dj/hybridprotokol/biography","https://soundcloud.com/hybrid-protokol"],"mix_url":["https://www.thewildcity.com/mixes/3136-wild-city-117-hybrid-protokol"]},"mix_note":"Wild City #117: Hybrid Protokol, 30-minute mix on The Wild City (Nov 2016)"}$v$::jsonb),updated_at=now() where slug=$v$hybrid-protokol$v$;
