update public.artists set bio=case when coalesce(bio,'')='' then $v$Karenn is a UK duo of Blawan and Pariah, formed in 2011 after they met releasing on R&S Records. They make and perform techno using analogue hardware. Their debut album Grapefruit Regret came out in 2019 on their label Voam.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Techno$v$] else genres end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://en.wikipedia.org/wiki/Karenn","https://nts.live/artists/7007-karenn"]}}$v$::jsonb),updated_at=now() where slug=$v$karenn$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Kiss Nuka is a Mumbai-based producer and audiovisual artist making dance floor electronic music with bass, ambient layers and distorted vocals. She released I Love The Drive on Ahead Of Our Time, a Ninja Tune sublabel, in 2022, after Matt Black of Coldcut signed her.$v$ else bio end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Mumbai, India$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"high","sources":{"bio":["https://mixmag.net/read/kiss-nuka-releases-new-single-i-love-the-drive-via-ninja-tune-news","https://kissnuka.bandcamp.com"],"based_city":["https://kissnuka.bandcamp.com","https://mixmag.net/read/kiss-nuka-releases-new-single-i-love-the-drive-via-ninja-tune-news"]}}$v$::jsonb),updated_at=now() where slug=$v$kiss-nuka$v$;
