update public.artists set bio=case when coalesce(bio,'')='' then $v$Maribou State are an English electronica duo from Berkhamsted, Hertfordshire. They release on Counter Records, an imprint of Ninja Tune, and earlier put out records on FatCat. Albums include Portraits (2015), Kingdoms in Colour (2018) and Hallucinating Love (2025).$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Electronica$v$] else genres end,instagram=case when coalesce(instagram,'')='' then $v$mariboustate$v$ else instagram end,website=case when coalesce(website,'')='' then $v$https://mariboustate.com/$v$ else website end,soundcloud=case when coalesce(soundcloud,'')='' then $v$https://soundcloud.com/mariboustate$v$ else soundcloud end,spotify=case when coalesce(spotify,'')='' then $v$https://open.spotify.com/artist/7zrkALJ9ayRjzysp4QYoEg$v$ else spotify end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://en.wikipedia.org/wiki/Maribou_State"],"genres":["https://en.wikipedia.org/wiki/Maribou_State"],"instagram":["https://mariboustate.com/"],"website":["https://mariboustate.com/"],"soundcloud":["https://mariboustate.com/"],"spotify":["https://mariboustate.com/"]}}$v$::jsonb),updated_at=now() where slug=$v$maribou-state$v$;
