update public.artists set bio=case when coalesce(bio,'')='' then $v$Natasha Diggs is a New York City DJ and the resident of the Soul in the Horn party series. She plays soul, funk, hip-hop, disco and Latin records, mostly on vinyl. She was the official DJ on Lauryn Hill's 2015 international tour.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Soul$v$,$v$Funk$v$,$v$Disco$v$,$v$Hip-Hop$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$New York, United States$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://mixmag.net/read/soul-in-the-horn-takeover-with-natasha-diggs-in-the-lab-nyc-the-lab"],"based_city":["https://mixmag.net/read/soul-in-the-horn-takeover-with-natasha-diggs-in-the-lab-nyc-the-lab"],"genres":["https://mixmag.net/read/soul-in-the-horn-takeover-with-natasha-diggs-in-the-lab-nyc-the-lab"]}}$v$::jsonb),updated_at=now() where slug=$v$natasha-diggs$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$NATE08 is Nathan Thomas, a Mumbai producer, DJ and bassist. His album Furaha came out on the UK label Needwant in November 2022. He plays house, funk and R&B.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$House$v$,$v$Funk$v$,$v$R&B$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Mumbai, India$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"high","sources":{"bio":["https://mixmag.asia/feature/nate08-interview-furaha","https://www.thewildcity.com/artists/11232-NATE08"],"based_city":["https://mixmag.asia/feature/nate08-interview-furaha","https://www.thewildcity.com/artists/11232-NATE08"],"genres":["https://mixmag.asia/feature/nate08-interview-furaha"]}}$v$::jsonb),updated_at=now() where slug=$v$nate08$v$;
