update public.artists set bio=case when coalesce(bio,'')='' then $v$Okedo is an electronic act from New Delhi built around Will Clark on synths and vocals and Ishaan Gandhi on drums and electronics. They released the EP New Fusion Movements with Pluto Monkey, and later a joint project, Okedolo, with Dolorblind.$v$ else bio end,based_city=case when coalesce(based_city,'') in ('','India') then $v$New Delhi, India$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://www.thewildcity.com/artists/12205-Okedo","https://homegrown.co.in/homegrown-creators/new-fusion-movements-listen-to-okedo-pluto-monkeys-new-layered-textural-ep"],"based_city":["https://www.thewildcity.com/artists/12205-Okedo"]}}$v$::jsonb),updated_at=now() where slug=$v$okedo$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Onra is Arnaud Bernard, a beatmaker and DJ from Paris. He released the Chinoiseries series, starting in 2007, and has put out records on All City and Fool's Gold. He hosts the NTS show Live From The 108.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Hip Hop$v$,$v$Electro$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Paris, France$v$ else based_city end,mix_url=case when coalesce(mix_url,'')='' then $v$https://www.nts.live/shows/live-from-the-108-w-onra/episodes/live-from-the-108-w-onra-26th-august-2024$v$ else mix_url end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://en.wikipedia.org/wiki/Onra","https://www.nts.live/artists/10273-onra"],"based_city":["https://www.nts.live/artists/10273-onra"],"mix_url":["https://www.nts.live/shows/live-from-the-108-w-onra/episodes/live-from-the-108-w-onra-26th-august-2024"]},"mix_note":"Live From The 108 w/ Onra, NTS, 26 Aug 2024 (house, new jack swing, R&B selections; player timer not confirmed)"}$v$::jsonb),updated_at=now() where slug=$v$onra$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Palms Trax is a producer and DJ based in Berlin. His first record came out in October 2013 on the London label Lobster Theremin, and he has since released on Rush Hour, Secretsundaze and Dekmantel. He plays house with a Detroit lean.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$House$v$,$v$Techno$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Berlin, Germany$v$ else based_city end,instagram=case when coalesce(instagram,'')='' then $v$palmstrax$v$ else instagram end,mix_url=case when coalesce(mix_url,'')='' then $v$https://www.nts.live/shows/solid-steel/episodes/solid_steelsolid-steel-radio-show-2722015-part-1-2-palms-trax$v$ else mix_url end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://ra.co/dj/palmstrax","https://www.simpleproductions.co.uk/artists/palms-trax/"],"based_city":["https://ra.co/dj/palmstrax"],"instagram":["https://ra.co/dj/palmstrax"],"mix_url":["https://www.nts.live/shows/solid-steel/episodes/solid_steelsolid-steel-radio-show-2722015-part-1-2-palms-trax"]},"mix_note":"Solid Steel on NTS, Palms Trax, 27 Feb 2015 (deep house, house, techno; no tracklist; player timer not confirmed)"}$v$::jsonb),updated_at=now() where slug=$v$palms-trax$v$;
