update public.artists set bio=case when coalesce(bio,'')='' then $v$Pulpy Shilpy is an electronic producer who works from a home studio in Pune. Her debut electro EP Slough was covered by Wild City. A second EP, heavy on disco and synths, was in progress, and she releases on OCL Records.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Electro$v$,$v$Disco$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Pune, India$v$ else based_city end,instagram=case when coalesce(instagram,'')='' then $v$pulpyshilpy$v$ else instagram end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://ra.co/dj/pulpyshilpy/biography","https://ra.co/dj/pulpyshilpy"],"based_city":["https://ra.co/dj/pulpyshilpy/biography"],"genres":["https://ra.co/dj/pulpyshilpy/biography"],"instagram":["https://ra.co/dj/pulpyshilpy"]}}$v$::jsonb),updated_at=now() where slug=$v$pulpy-shilpy$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Ross From Friends is Felix Clary Weatherall, from Brightlingsea in Essex, England. He makes house and dub techno and records for Brainfeeder. His albums are Family Portrait (2018) and Tread (2021).$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$House$v$,$v$Dub Techno$v$] else genres end,website=case when coalesce(website,'')='' then $v$https://rossfromfriends.net$v$ else website end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://en.wikipedia.org/wiki/Ross_from_Friends","https://mixmag.net/read/ross-from-friends-unites-with-brainfeeder-news"],"genres":["https://en.wikipedia.org/wiki/Ross_from_Friends"],"website":["https://rossfromfriends.net"]}}$v$::jsonb),updated_at=now() where slug=$v$ross-from-friends$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Shantam Khanna is a producer from Noida who got into electronic music through trance in 2007. His work moves between ambient drones and techno. He releases on OCL Records and plays keys in the band FOPCHU.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Ambient$v$,$v$Techno$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Noida, India$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://ra.co/dj/shantam/biography","https://ra.co/dj/shantam"],"genres":["https://ra.co/dj/shantam/biography"],"based_city":["https://ra.co/dj/shantam"]}}$v$::jsonb),updated_at=now() where slug=$v$shantam$v$;
