update public.artists set bio=case when coalesce(bio,'')='' then $v$Shireen is a Delhi DJ and a member of the all-femme collective Coven Code. Her sets draw on UK club culture, mixing house and techno with UK garage, breakbeat and dubstep.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$House$v$,$v$Techno$v$,$v$UK Garage$v$,$v$Breakbeat$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Delhi, India$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://www.thewildcity.com/artists/12022-shireen"],"based_city":["https://www.thewildcity.com/artists/12022-shireen"],"genres":["https://www.thewildcity.com/artists/12022-shireen"]}}$v$::jsonb),updated_at=now() where slug=$v$shireen$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Sijya is a South Asian composer, producer and graphic artist. Her debut EP was Young Hate, and her second, Leather & Brass, came out on One Little Independent Records. She has appeared on RA's Mix of the Day, NTS and Refuge Worldwide.$v$ else bio end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://www.sijya.com/bio"]}}$v$::jsonb),updated_at=now() where slug=$v$sijya$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Simo Cell is Simon Aussel, a producer and DJ born in Nantes and based in Paris. He plays UK bass, techno, breaks and left-field club music. He runs the label TEMET, released early records on Dnuos Ytivil and Fragil Musique, and recorded RA Podcast 934 in 2024.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Bass$v$,$v$Techno$v$,$v$Breaks$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Paris, France$v$ else based_city end,mix_url=case when coalesce(mix_url,'')='' then $v$https://ra.co/podcast/934$v$ else mix_url end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"high","sources":{"bio":["https://control.eventbook.ro/editorial/artist-profile-simo-cell","https://ra.co/podcast/934"],"based_city":["https://ra.co/podcast/934","https://control.eventbook.ro/editorial/artist-profile-simo-cell"],"mix_url":["https://ra.co/podcast/934"]},"mix_note":"RA.934 Simo Cell, Resident Advisor Podcast, April 2024 (1h47)"}$v$::jsonb),updated_at=now() where slug=$v$simo-cell$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Spryk is Tejas Nair, an electronic musician and media artist based in Mumbai. He makes bass-led electronic music and audiovisual shows, and has released the EP Afterglow. He runs the Skip-A-Beat label and played Lollapalooza India in 2025.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Electronic$v$,$v$Bass$v$,$v$Halftime$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Mumbai, India$v$ else based_city end,soundcloud=case when coalesce(soundcloud,'')='' then $v$https://soundcloud.com/spryk$v$ else soundcloud end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"high","sources":{"bio":["https://soundcloud.com/spryk","https://www.thewildcity.com/artists/293-Spryk"],"based_city":["https://soundcloud.com/spryk"],"soundcloud":["https://soundcloud.com/spryk"]}}$v$::jsonb),updated_at=now() where slug=$v$spryk$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Stain is Sourodeep Guha, a DJ and producer based in Delhi. He plays bass-heavy club music rooted in sound system culture, with dub and Afrobeat influences. He co-founded the Delhi bass collective Sub-Z and has had support from Om Unit, dBridge, Zed Bias and Mala.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$Bass$v$,$v$Dub$v$,$v$Afrobeat$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Delhi, India$v$ else based_city end,mix_url=case when coalesce(mix_url,'')='' then $v$https://www.thewildcity.com/mixes/15203-wild-city-182-stain$v$ else mix_url end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://refugeworldwide.com/artists/stain","https://www.thewildcity.com/mixes/15203-wild-city-182-stain"],"based_city":["https://refugeworldwide.com/artists/stain","https://www.thewildcity.com/mixes/15203-wild-city-182-stain"],"mix_url":["https://www.thewildcity.com/mixes/15203-wild-city-182-stain"]},"mix_note":"Wild City #182: Stain, Wild City, October 2019"}$v$::jsonb),updated_at=now() where slug=$v$stain$v$;
