update public.artists set bio=case when coalesce(bio,'')='' then $v$TaoFu is Fuong Nguyen, a Vietnamese DJ who began playing in 2020. She is a resident at The Observatory in Saigon and a member of the ATIPIK Collective. She has played Magnetic Fields in India and The Air House Festival in Korea.$v$ else bio end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://mixmag.asia/read/yes-you-singapore-second-anniversary-taofu-debut-taaka-farewell-events"]}}$v$::jsonb),updated_at=now() where slug=$v$tao-fu$v$;
update public.artists set bio=case when coalesce(bio,'')='' then $v$Violet is Ines Borges Coutinho, a DJ and producer based in Lisbon. She plays tough house, rhythmic techno and breakbeat. She co-founded the party mina and Radio Quantica, released the New Visions EP on Paraiso, and announced her debut album Bed of Roses for Dark Entries.$v$ else bio end,genres=case when genres is null or cardinality(genres)=0 or genres=array['Electronic'] then array[$v$House$v$,$v$Techno$v$,$v$Breakbeat$v$] else genres end,based_city=case when coalesce(based_city,'') in ('','India') then $v$Lisbon, Portugal$v$ else based_city end,enrich_sources=coalesce(enrich_sources,'{}'::jsonb)||jsonb_build_object('profile_research',$v${"at":"2026-10-31","confidence":"medium","sources":{"bio":["https://direct.djmag.com/content/recognise-violet"],"based_city":["https://direct.djmag.com/content/recognise-violet"]}}$v$::jsonb),updated_at=now() where slug=$v$violet$v$;
